"""PDF: title and author from the document info dictionary (no cover rendering)."""

from __future__ import annotations

import logging
import re
from pathlib import Path

from pypdf import PdfReader

from .base import BookMetadata, register

logging.getLogger("pypdf").setLevel(logging.ERROR)

# Titles generated by authoring tools rather than written by a human.
_JUNK_TITLE = re.compile(r"^(untitled|microsoft word|.+\.(docx?|pdf|indd|tex|dvi|odt)$)", re.I)


@register("pdf")
def extract_pdf(path: Path) -> BookMetadata:
    info = PdfReader(path).metadata
    if info is None:
        return BookMetadata()
    title = str(info.title or "").strip()
    return BookMetadata(
        title=None if _JUNK_TITLE.match(title) else title or None,
        author=str(info.author or "").strip() or None,
    )
